def build_missing_nodes() -> list[Path]:
    OUT.mkdir(parents=True, exist_ok=True)
    written = []
    for slug, guide in GUIDES.items():
        path = OUT / f'{slug}.md'
        if path.exists():
            continue
        path.write_text(render(slug, guide), encoding='utf-8')
        written.append(path)
    return written


if __name__ == '__main__':
    for path in build_missing_nodes():
        print(path.name)
